514	    border-radius: 16px;
515	    color: #fff;
516	  }}
517	  .report-header h1 {{
518	    font-size: 28px;
519	    font-weight: 700;
520	    margin-bottom: 12px;
521	    letter-spacing: -0.5px;
522	  }}
523	  .report-header .subtitle {{
524	    font-size: 15px;
525	    opacity: 0.85;
526	    max-width: 700px;
527	    margin: 0 auto;
528	  }}
529	  .report-header .meta {{
530	    font-size: 12px;
531	    opacity: 0.6;
532	    margin-top: 16px;
533	  }}
534	
535	  .section {{
536	    margin-bottom: 48px;
537	  }}
538	  .section-title {{
539	    font-size: 22px;
540	    font-weight: 700;
541	    color: var(--primary);
542	    margin-bottom: 8px;
543	    padding-bottom: 8px;
544	    border-bottom: 3px solid var(--accent);
545	    display: inline-block;
546	  }}
