565	    transition: box-shadow 0.2s;
566	  }}
567	  .kpi-card:hover {{
568	    box-shadow: 0 4px 20px rgba(0,0,0,0.06);
569	  }}
570	  .kpi-value {{
571	    font-size: 32px;
572	    font-weight: 700;
573	    color: var(--accent);
574	    margin-bottom: 4px;
575	  }}
576	  .kpi-value.green {{ color: var(--green); }}
577	  .kpi-value.orange {{ color: var(--accent2); }}
578	  .kpi-label {{
579	    font-size: 13px;
580	    color: var(--text-light);
581	    font-weight: 500;
582	  }}
583	
584	  .card {{
585	    background: var(--card-bg);
586	    border: 1px solid var(--border);
587	    border-radius: 12px;
588	    padding: 28px;
589	    margin-bottom: 24px;
590	  }}
591	  .card h3 {{
592	    font-size: 16px;
593	    font-weight: 600;
594	    margin-bottom: 16px;
595	    color: var(--primary);
596	  }}
597	
598	  .chart-row {{
599	    display: grid;
600	    grid-template-columns: 1fr 1fr;
601	    gap: 24px;
602	    margin-bottom: 24px;
603	  }}
604	  @media (max-width: 800px) {{
605	    .chart-row {{ grid-template-columns: 1fr; }}
606	  }}
607	  .chart-container {{
608	    background: var(--card-bg);
609	    border: 1px solid var(--border);
610	    border-radius: 12px;
611	    padding: 20px;
612	    overflow-x: auto;
613	  }}
614	
615	  .data-table {{
616	    width: 100%;
617	    border-collapse: collapse;
618	    font-size: 13px;
619	  }}
620	  .data-table th {{
621	    background: #f1f4f8;
622	    padding: 10px 14px;
623	    text-align: left;
624	    font-weight: 600;
625	    color: var(--primary);
626	    border-bottom: 2px solid var(--border);
627	    white-space: nowrap;
628	  }}
629	  .data-table td {{
