631	    border-bottom: 1px solid var(--border);
632	  }}
633	  .data-table tbody tr:hover {{
634	    background: #f8fafd;
635	  }}
636	  .data-table.compact td, .data-table.compact th {{
637	    padding: 7px 10px;
