656	  }}
657	
658	  .rec-list {{
659	    list-style: none;
660	    counter-reset: rec;
661	  }}
662	  .rec-list li {{
663	    counter-increment: rec;
664	    padding: 20px 20px 20px 56px;
665	    position: relative;
666	    border-bottom: 1px solid var(--border);
667	  }}
668	  .rec-list li:last-child {{ border-bottom: none; }}
669	  .rec-list li::before {{
670	    content: counter(rec);
671	    position: absolute;
672	    left: 16px;
673	    top: 20px;
674	    width: 28px;
