691	    font-size: 12px;
692	    color: var(--accent);
693	    font-weight: 600;
694	    margin-top: 6px;
695	  }}
696	
697	  .footer {{
698	    text-align: center;
699	    color: var(--text-light);
700	    font-size: 12px;
701	    padding: 32px 0 16px;
702	    border-top: 1px solid var(--border);
703	    margin-top: 48px;
